mapper.select:
SELECT COALESCE(SUM(e.amount), 0)
FROM expenses e
WHERE e.user_id = #{userId}
    AND (
            (
                e.expense_date >= #{monthStart}
                AND e.expense_date < #{nextMonthStart}
            )
            OR
            (
                e.expense_date IS NULL
                AND e.created_at >= #{createdAtStart}
                AND e.created_at < #{createdAtEnd}
            )
    )

SELECT COALESCE(SUM(e.amount), 0)
FROM expenses e
WHERE e.user_id = #{userId}
    AND e.expense_date = #{today}

SELECT
    e.category_id,
    c.name AS category_name,
    c.color AS category_color,
    SUM(e.amount) AS total_amount
FROM expenses e
JOIN categories c ON e.category_id = c.id
WHERE e.user_id = #{userId}
    AND (
            (
                e.expense_date >= #{monthStart}
                AND e.expense_date < #{nextMonthStart}
            )
            OR
            (
                e.expense_date IS NULL
                AND e.created_at >= #{createdAtStart}
                AND e.created_at < #{createdAtEnd}
            )
    )
GROUP BY e.category_id, c.name, c.color
HAVING SUM(e.amount) > 0
ORDER BY total_amount DESC, e.category_id ASC

SELECT COALESCE(SUM(e.amount), 0)
FROM expenses e
WHERE e.user_id = #{userId}
    AND e.expense_date IS NULL
    AND e.created_at >= #{createdAtStart}
    AND e.created_at < #{createdAtEnd}

SELECT e.id, e.amount, e.category_id, c.name AS category_name, c.color AS category_color, e.memo, e.expense_date, e.expense_time, e.created_at FROM expenses e JOIN categories c ON e.category_id = c.id
AND (
e.expense_date IS NULL OR e.expense_date < #{cursor.expenseDate} OR ( e.expense_date = #{cursor.expenseDate} AND )
e.expense_date IS NULL AND
)
ORDER BY e.expense_date IS NULL ASC, e.expense_date DESC, e.expense_time IS NULL ASC, e.expense_time DESC, e.created_at DESC, e.id DESC LIMIT #{limit}

mapper.update:
UPDATE expenses
SET
    amount = #{expense.amount},
    category_id = #{expense.categoryId},
    memo = #{expense.memo},
    expense_date = #{expense.expenseDate},
    expense_time = #{expense.expenseTime}
WHERE id = #{expense.id}
    AND user_id = #{userId}

mapper.delete:
DELETE FROM expenses
WHERE id = #{id}
    AND user_id = #{userId}
